import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is calibreweb-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787093302000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-calibreweb-mcp" tabindex="-1">What is calibreweb-mcp? <a class="header-anchor" href="#what-is-calibreweb-mcp" aria-label="Permalink to “What is calibreweb-mcp?”">​</a></h1><p><a href="https://github.com/janeczku/calibre-web" target="_blank" rel="noreferrer">Calibre-Web</a> is the self-hosted web UI for a <a href="https://calibre-ebook.com" target="_blank" rel="noreferrer">Calibre</a> ebook library, and <a href="https://github.com/crocodilestick/Calibre-Web-Automated" target="_blank" rel="noreferrer">Calibre-Web Automated</a> is its actively extended fork. Both serve the same machine-readable interface: an <a href="https://opds.io" target="_blank" rel="noreferrer">OPDS</a> catalog feed under <code>/opds</code>, built so e-reader apps can browse and download books.</p><p><code>calibreweb-mcp</code> puts that feed behind the <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a>, so an assistant can answer &quot;do we have anything by Le Guin?&quot;, pick something from a shelf, show a cover, or hand you the EPUB download link — without you opening the web UI.</p><h2 id="why-not-talk-to-the-api-directly" tabindex="-1">Why not talk to the API directly? <a class="header-anchor" href="#why-not-talk-to-the-api-directly" aria-label="Permalink to “Why not talk to the API directly?”">​</a></h2><p>Because there is no API. Calibre-Web has no REST endpoints; feature requests for one have been open for years. What it has is the OPDS feed: Atom XML designed for e-reader firmware, not for programs that want structured data.</p><table tabindex="0"><thead><tr><th>The feed gives you</th><th>These tools give you</th></tr></thead><tbody><tr><td>Atom XML with three namespaces</td><td>JSON</td></tr><tr><td><code>&lt;id&gt;urn:uuid:…&lt;/id&gt;</code> and no numeric id anywhere</td><td>the numeric book id, extracted from the cover/download links</td></tr><tr><td>rating, series and tags rendered into an XHTML blob</td><td><code>rating: 4</code>, <code>series: { name, index }</code>, <code>tags: […]</code></td></tr><tr><td>the book comment as escaped HTML inside that blob</td><td>a plain-text summary, bounded per book and per response</td></tr><tr><td>root-relative hrefs</td><td>absolute download and cover URLs, locked to your instance&#39;s origin</td></tr><tr><td>a <code>rel=&quot;next&quot;</code> link when more pages exist</td><td><code>pagination.nextOffset</code> to pass back as <code>offset</code></td></tr></tbody></table><h2 id="what-it-deliberately-does-not-do" tabindex="-1">What it deliberately does not do <a class="header-anchor" href="#what-it-deliberately-does-not-do" aria-label="Permalink to “What it deliberately does not do”">​</a></h2><ul><li><strong>No writes.</strong> The OPDS feed has none, and this server would not add any. There is nothing to configure to make it read-only — it is read-only by construction.</li><li><strong>No file downloads.</strong> Tools return download URLs per format; the model has no reason to pull an EPUB into its context. Covers are the one exception — they come back as real images your client can display.</li><li><strong>No facet browsing.</strong> Authors, series, tags and publishers exist as index feeds, but <code>search_books</code> covers those lookups; dedicated tools can be added if a real use case shows up.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — create a dedicated user and run the server</li><li><a href="/guide/clients">Connecting clients</a> — Claude Code, Claude Desktop, Codex, Docker</li><li><a href="/guide/security">Security</a> — what the credentials grant and how metadata is treated</li></ul>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};